private val isGerman: Boolean get() = Settings.language == Language.GERMAN

// What the players read: the card's own words, or their German while the game speaks German. Reading these inside a composable follows the language.
val Card.shownTitle: String get() = if (isGerman) german[title]?.title ?: title else title

val Card.shownDescription: String get() = if (isGerman) german[title]?.description ?: description else description

val CardKind.shownLabel: String get() = if (isGerman) germanKinds.getValue(this) else label
